import React, { useState } from 'react';
import { APP_VERSION } from '../firebase';
import { checkNewPassword } from '../auth';
import { getTeamPublic, teamIdFromName, accountExists, signInAccount, createAccountAndJoin, createTeamAndJoin } from '../accounts';
import { NebulaCanvas } from '../components';

const WeakNotice = ({ reasons }) => reasons.length ? (
  <div style={{ fontSize:12, lineHeight:1.55, color:'#f59e0b', background:'rgba(245,158,11,0.1)', border:'1px solid rgba(245,158,11,0.35)', borderRadius:10, padding:'10px 12px' }}>
    This password is easy to guess: {reasons.join('; ')}. A longer one with letters, numbers and symbols is safer. Press the button again to use it anyway.
  </div>
) : null;

const OnboardingScreen = ({ onComplete, T }) => {
  const [step, setStep] = useState('team');      // 'team' -> 'account'
  const [mode, setMode] = useState(null);          // 'create' | 'join' (the team)
  const [teamNameInput, setTeamNameInput] = useState('');
  const [teamPassInput, setTeamPassInput] = useState('');
  const [teamPassConfirm, setTeamPassConfirm] = useState('');
  const [userNameInput, setUserNameInput] = useState('');
  const [userMode, setUserMode] = useState(null);  // null = asking for the name | 'login' | 'create'
  const [passInput, setPassInput] = useState('');
  const [passConfirm, setPassConfirm] = useState('');
  const [weakReasons, setWeakReasons] = useState([]);
  const [weakAck, setWeakAck] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [logoDataUrl, setLogoDataUrl] = useState(() => localStorage.getItem('crm_logo') || null);
  const [dragActive, setDragActive] = useState(false);

  const teamId = teamIdFromName(teamNameInput);
  const friendly = (e) => ({
    'bad-password': 'Incorrect password',
    'too-many': 'Too many attempts. Please wait a few minutes and try again.',
    'no-account': 'There is no account with that name in this team.',
    'name-taken': 'That name is already taken in this team.',
    'bad-team-password': 'Incorrect team password',
    'need-team-password': 'Enter the team password to join this team.',
    'weak-password': 'That password is too weak. Use at least 6 characters.',
    'network': 'No connection. Check your internet and try again.',
    'auth-disabled': 'Email/Password sign-in is not enabled in the Firebase console yet.',
    'team-exists': 'This team name is already in use',
    'no-team': 'Team not found',
  }[e && e.code] || ('Error: ' + (e && e.message)));
  const resetAccountStage = () => { setUserMode(null); setPassInput(''); setPassConfirm(''); setWeakReasons([]); setWeakAck(false); setError(''); };

  // Step 1: the team. Nothing is created yet, the account step finishes the job.
  const handleTeamNext = async () => {
    if (!teamNameInput.trim()) { setError('Team name is required'); return; }
    if (mode === 'create') {
      if (!teamPassInput) { setError('Team password is required'); return; }
      const chk = checkNewPassword(teamPassInput, teamPassConfirm, [teamNameInput], weakAck);
      if (chk.error) { setError(chk.error); return; }
      if (chk.weak) { setWeakReasons(chk.weak); setWeakAck(true); setError(''); return; }
    }
    setLoading(true); setError('');
    try {
      const team = await getTeamPublic(teamId);
      if (mode === 'create' && team) { setError('This team name is already in use'); setLoading(false); return; }
      if (mode === 'join' && !team) { setError('Team not found'); setLoading(false); return; }
      resetAccountStage();
      if (mode === 'create') setUserMode('create');
      setStep('account');
    } catch (e) { setError(friendly(e)); }
    setLoading(false);
  };

  // Account step, stage 1 (joining only): is this a returning member or a new one?
  const handleCheckName = async () => {
    const name = userNameInput.trim();
    if (!name) { setError('Username is required'); return; }
    setLoading(true); setError('');
    try { setUserMode((await accountExists(teamId, name)) ? 'login' : 'create'); setPassInput(''); setPassConfirm(''); setWeakReasons([]); setWeakAck(false); }
    catch (e) { setError(friendly(e)); }
    setLoading(false);
  };

  // Account step, stage 2: sign in, or create the account (and the team, when creating one).
  const handleSubmitAccount = async () => {
    const name = userNameInput.trim();
    if (!name) { setError('Username is required'); return; }
    setLoading(true); setError('');
    try {
      let session;
      if (userMode === 'login') {
        session = await signInAccount(teamId, name, passInput);
      } else {
        const chk = checkNewPassword(passInput, passConfirm, [name, teamNameInput], weakAck);
        if (chk.error) { setError(chk.error); setLoading(false); return; }
        if (chk.weak) { setWeakReasons(chk.weak); setWeakAck(true); setLoading(false); return; }
        session = mode === 'create'
          ? await createTeamAndJoin({ teamName: teamNameInput, teamPassword: teamPassInput, name, password: passInput })
          : await createAccountAndJoin({ teamId, teamPassword: teamPassInput, name, password: passInput });
      }
      onComplete(session);
    } catch (e) { setError(friendly(e)); }
    setLoading(false);
  };

  const handleLogoUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => { localStorage.setItem('crm_logo', ev.target.result); setLogoDataUrl(ev.target.result); };
    reader.readAsDataURL(file);
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = (ev) => { localStorage.setItem('crm_logo', ev.target.result); setLogoDataUrl(ev.target.result); };
        reader.readAsDataURL(file);
      }
    }
  };

  return (
    <div style={{ minHeight:'100vh', display:'flex', alignItems:'center', justifyContent:'center', background: T.bg, color: T.text, fontFamily:"'DM Sans',system-ui,sans-serif", position:'relative', overflow:'hidden' }}>
      <NebulaCanvas theme="dark" />
      <div style={{ position:'relative', zIndex:2, width:'100%', maxWidth:480, padding:20 }}>
        <div style={{ textAlign:'center', marginBottom:32 }}>
          <h1 style={{ fontSize:28, fontWeight:900, margin:0, background:'linear-gradient(135deg,var(--accent,#38bdf8),#a855f7)', WebkitBackgroundClip:'text', WebkitTextFillColor:'transparent' }}>C-Rem Studios</h1>
          <p style={{ fontSize:13, color:T.muted, marginTop:8 }}>Team Task Manager v{APP_VERSION}</p>
        </div>

        <div style={{ background:T.card, borderRadius:24, border:`1px solid ${T.border}`, padding:32, boxShadow:'0 40px 100px rgba(0,0,0,0.4)' }}>
          {step === 'team' ? (
            <>
              <h2 style={{ fontSize:18, fontWeight:800, margin:'0 0 20px', textAlign:'center' }}>Team Selection</h2>
              <div style={{ display:'flex', gap:12, marginBottom:24 }}>
                <button 
                  onClick={() => setMode('create')} 
                  onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-4px) scale(1.02)'; e.currentTarget.style.boxShadow = `0 12px 28px ${'color-mix(in srgb, var(--accent,#38bdf8) 27%, transparent)'}`; }}
                  onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0) scale(1)'; e.currentTarget.style.boxShadow = 'none'; }}
                  style={{ flex:1, padding:20, borderRadius:16, border:`2px solid ${mode==='create'?'var(--accent,#38bdf8)':T.border}`, background:mode==='create'?'color-mix(in srgb, var(--accent,#38bdf8) 10%, transparent)':T.sub, color:mode==='create'?'var(--accent,#38bdf8)':T.text, cursor:'pointer', transition:'all 0.2s', display:'flex', flexDirection:'column', alignItems:'center', gap:8 }}>
                  <span style={{ fontSize:32 }}>🏗️</span>
                  <span style={{ fontSize:13, fontWeight:800 }}>Create New Team</span>
                </button>
                <button 
                  onClick={() => setMode('join')} 
                  onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-4px) scale(1.02)'; e.currentTarget.style.boxShadow = `0 12px 28px ${'#a855f744'}`; }}
                  onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0) scale(1)'; e.currentTarget.style.boxShadow = 'none'; }}
                  style={{ flex:1, padding:20, borderRadius:16, border:`2px solid ${mode==='join'?'#a855f7':T.border}`, background:mode==='join'?'rgba(168,85,247,0.1)':T.sub, color:mode==='join'?'#a855f7':T.text, cursor:'pointer', transition:'all 0.2s', display:'flex', flexDirection:'column', alignItems:'center', gap:8 }}>
                  <span style={{ fontSize:32 }}>🤝</span>
                  <span style={{ fontSize:13, fontWeight:800 }}>Join a Team</span>
                </button>
              </div>
              {mode && (
                <div style={{ display:'flex', flexDirection:'column', gap:12, animation:'fadeSlide 0.3s ease' }}>
                  <input style={{ padding:'12px 16px', borderRadius:12, border:`1px solid ${T.border}`, background:T.sub, color:T.text, outline:'none', fontSize:14 }} placeholder="Team Name" value={teamNameInput} onChange={e=>setTeamNameInput(e.target.value)} />
                  <input type="password" style={{ padding:'12px 16px', borderRadius:12, border:`1px solid ${T.border}`, background:T.sub, color:T.text, outline:'none', fontSize:14 }} placeholder={mode==='join' ? "Team password (first time only)" : "Team Password"} value={teamPassInput} onChange={e=>{setTeamPassInput(e.target.value);setWeakReasons([]);setWeakAck(false);}} />
                  {mode==='create' && <input type="password" style={{ padding:'12px 16px', borderRadius:12, border:`1px solid ${T.border}`, background:T.sub, color:T.text, outline:'none', fontSize:14 }} placeholder="Confirm team password" value={teamPassConfirm} onChange={e=>{setTeamPassConfirm(e.target.value);setWeakReasons([]);setWeakAck(false);}} />}
                  {mode==='create' && <WeakNotice reasons={weakReasons} />}
                  {error && <div style={{ color:'#ef4444', fontSize:12, fontWeight:700, textAlign:'center' }}>{error}</div>}
                  <button onClick={handleTeamNext} disabled={loading} style={{ padding:14, borderRadius:12, border:'none', background:'linear-gradient(135deg,var(--accent,#38bdf8),#0284c7)', color:'#fff', fontWeight:800, fontSize:14, cursor:'pointer', opacity:loading?0.6:1 }}>
                    {loading ? '⏳ Processing...' : mode==='create' ? (weakAck ? 'Continue with this password' : 'Continue') : 'Continue'}
                  </button>
                  {mode === 'create' && (
                    <div style={{ marginTop:16, padding:14, borderRadius:12, background:T.sub, border:`1px dashed ${T.border}` }}>
                      <div style={{ fontSize:11, fontWeight:700, color:T.muted, marginBottom:8 }}>🎨 Upload Logo (Optional)</div>
                      <label style={{ display:'block', position:'relative', cursor:'pointer', overflow:'hidden', borderRadius:10, background:dragActive?'color-mix(in srgb, var(--accent,#38bdf8) 13%, transparent)':T.card, border:`1px solid ${dragActive?'var(--accent,#38bdf8)':T.border}`, padding:'16px', textAlign:'center', transition:'all 0.2s' }}
                        onDragEnter={handleDrag}
                        onDragLeave={handleDrag}
                        onDragOver={handleDrag}
                        onDrop={handleDrop}
                        onMouseEnter={(e) => { if (!dragActive) { e.currentTarget.style.borderColor = 'var(--accent,#38bdf8)'; e.currentTarget.style.background = 'color-mix(in srgb, var(--accent,#38bdf8) 7%, transparent)'; } }}
                        onMouseLeave={(e) => { if (!dragActive) { e.currentTarget.style.borderColor = T.border; e.currentTarget.style.background = T.card; } }}>
                        <input type="file" accept="image/*" onChange={handleLogoUpload} style={{ display:'none' }} />
                        {!logoDataUrl ? (
                          <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:6, transform:dragActive?'scale(1.05)':'scale(1)', transition:'transform 0.2s' }}>
                            <div style={{ fontSize:24, animation:dragActive?'logoFloat 0.6s ease-in-out infinite':'none' }}>📤</div>
                            <div style={{ fontSize:11, fontWeight:700, color:dragActive?'var(--accent,#38bdf8)':T.text }}>Click to select an image</div>
                            <div style={{ fontSize:9, color:dragActive?'var(--accent,#38bdf8)':T.muted }}>or drag &amp; drop</div>
                          </div>
                        ) : (
                          <div style={{ display:'flex', alignItems:'center', gap:10 }}>
                            <div style={{ position:'relative' }}>
                              <img src={logoDataUrl} style={{ width:50, height:50, objectFit:'contain', borderRadius:8, animation:'logoFloat 2.5s ease-in-out infinite' }} alt="Logo Preview" />
                              <div style={{ position:'absolute', inset:0, borderRadius:8, boxShadow:'0 0 16px color-mix(in srgb, var(--accent,#38bdf8) 50%, transparent)', animation:'logoPulse 2s ease-in-out infinite' }} />
                            </div>
                            <div style={{ textAlign:'left' }}>
                              <div style={{ fontSize:10, fontWeight:700, color:T.text, display:'flex', alignItems:'center', gap:6 }}>
                                <span>✓ Logo Selected</span>
                                <span style={{ animation:'checkBounce 0.6s cubic-bezier(.175,.885,.32,1.275)' }}>✨</span>
                              </div>
                              <div style={{ fontSize:9, color:T.muted, marginTop:2 }}>Click to change</div>
                            </div>
                          </div>
                        )}
                      </label>
                      <div style={{ fontSize:10, color:T.muted, marginTop:6 }}>This logo will be your team's icon.</div>
                    </div>
                  )}
                </div>
              )}
            </>
          ) : (
            <>
              <div style={{ textAlign:'center', marginBottom:20 }}>
                {logoDataUrl && <img src={logoDataUrl} style={{ width:70, height:70, objectFit:'contain', marginBottom:12, filter:'drop-shadow(0 6px 20px color-mix(in srgb, var(--accent,#38bdf8) 40%, transparent))', borderRadius:16 }} alt="Team Logo" />}
              </div>
              <h2 style={{ fontSize:18, fontWeight:800, margin:'0 0 20px', textAlign:'center' }}>{userMode===null ? 'Your Username' : userMode==='login' ? 'Welcome back' : 'Create your account'}</h2>
              <div style={{ display:'flex', flexDirection:'column', gap:12, animation:'fadeSlide 0.3s ease' }}>
                <input style={{ padding:'12px 16px', borderRadius:12, border:`1px solid ${T.border}`, background:T.sub, color:T.text, outline:'none', fontSize:14 }} placeholder="Your name / nickname" value={userNameInput} disabled={userMode!==null && mode!=='create'} onChange={e=>setUserNameInput(e.target.value)} onKeyPress={e=>e.key==='Enter'&&userMode===null&&handleCheckName()} autoFocus />
                {userMode==='login' && <div style={{ fontSize:12, lineHeight:1.55, color:T.muted }}>Welcome back. The team password is not needed to sign in.</div>}
                {userMode!==null && <input type="password" style={{ padding:'12px 16px', borderRadius:12, border:`1px solid ${T.border}`, background:T.sub, color:T.text, outline:'none', fontSize:14 }} placeholder={userMode==='login' ? 'Your password' : 'Choose a password'} value={passInput} onChange={e=>{setPassInput(e.target.value);setWeakReasons([]);setWeakAck(false);}} onKeyPress={e=>e.key==='Enter'&&userMode==='login'&&handleSubmitAccount()} autoFocus />}
                {userMode==='create' && <input type="password" style={{ padding:'12px 16px', borderRadius:12, border:`1px solid ${T.border}`, background:T.sub, color:T.text, outline:'none', fontSize:14 }} placeholder="Repeat password" value={passConfirm} onChange={e=>{setPassConfirm(e.target.value);setWeakReasons([]);setWeakAck(false);}} onKeyPress={e=>e.key==='Enter'&&handleSubmitAccount()} />}
                {userMode==='create' && <WeakNotice reasons={weakReasons} />}
                {error && <div style={{ color:'#ef4444', fontSize:12, fontWeight:700, textAlign:'center' }}>{error}</div>}
                <button 
                  onClick={userMode===null ? handleCheckName : handleSubmitAccount} 
                  disabled={loading} 
                  onMouseEnter={(e) => { if(!loading) { e.currentTarget.style.transform = 'translateY(-4px) scale(1.03)'; e.currentTarget.style.boxShadow = '0 14px 32px rgba(16,185,129,0.45)'; } }}
                  onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0) scale(1)'; e.currentTarget.style.boxShadow = 'none'; }}
                  style={{ padding:14, borderRadius:12, border:'none', background:'linear-gradient(135deg,#10b981,#059669)', color:'#fff', fontWeight:800, fontSize:14, cursor:'pointer', opacity:loading?0.6:1, transition:'all 0.2s' }}>
                  {loading ? '⏳ Please wait...' : userMode===null ? 'Continue' : userMode==='login' ? '✅ Sign in' : weakAck ? 'Use this password anyway' : '✅ Create account'}
                </button>
                <button 
                  onClick={() => (userMode===null || mode==='create') ? (resetAccountStage(), setStep('team')) : resetAccountStage()} 
                  onMouseEnter={(e) => { e.currentTarget.style.color = 'var(--accent,#38bdf8)'; e.currentTarget.style.transform = 'translateX(-4px)'; }}
                  onMouseLeave={(e) => { e.currentTarget.style.color = T.muted; e.currentTarget.style.transform = 'translateX(0)'; }}
                  style={{ padding:10, borderRadius:12, border:'none', background:'transparent', color:T.muted, fontWeight:700, fontSize:12, cursor:'pointer', transition:'all 0.2s' }}>{(userMode===null || mode==='create') ? '← Go Back' : '← Use a different name'}</button>
              </div>
            </>
          )}
        </div>
        <div style={{ textAlign:'center', marginTop:20, fontSize:11, color:T.muted, opacity:0.5 }}>C-Rem Studios © 2026 | v{APP_VERSION} | 👥 Designed for Teamwork</div>
      </div>
    </div>
  );
};

export default OnboardingScreen;