    const yap = tasks.filter(t=>t.status==="Yapılacaklar").filter(matchesDueFilter).filter(matchesSearch);
    const sf = sortByPriority
      ? (a,b) => (PRIORITY_ORDER[a.priority]||5) - (PRIORITY_ORDER[b.priority]||5) || (a.order??a.createdAt??0) - (b.order??b.createdAt??0)
      : (a,b) => (a.order??a.createdAt??0) - (b.order??b.createdAt??0);
    if (selectedCat) return [{ category:selectedCat, color:catColor(selectedCat), tasks:yap.filter(t=>t.category===selectedCat).sort(sf) }];
    const res = [];
    const orderedCats = primaryBranch ? [...categories.filter(c=>c.name===primaryBranch), ...categories.filter(c=>c.name!==primaryBranch)] : categories;
    orderedCats.forEach(c => {
      const ct = yap.filter(t=>t.category===c.name).sort(sf);
      if (ct.length) res.push({ category:c.name, color:c.color, tasks:ct, isPrimary:c.name===primaryBranch });
    });
    const nc = yap.filter(t=>!t.category).sort(sf);
    if (nc.length) res.push({ category:null, color:'#475569', tasks:nc, isPrimary:false });
