  const toggleVoiceInput = useCallback(async () => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const warn = (msg) => { setLimitWarning(msg); setTimeout(() => setLimitWarning(null), 9000); };
    if (!SpeechRecognition) { warn('Voice input is not supported in this build.'); return; }
    if (isListening) { recognitionRef.current?.stop(); return; }

    // Before starting, check the microphone. Windows shows NO pop-up to desktop apps: the switch lives in
    // Settings > Privacy & security > Microphone. So ask the OS (electron.js: 'mic-status') and, if it is off,
    // offer to open that page. In a normal browser, getUserMedia is what makes the permission pop-up appear.
    const openMicSettings = () => {
      if (ipcRenderer && window.confirm('Microphone access is turned off for desktop apps.\n\nOpen the Windows microphone settings now? Turn on "Let desktop apps access your microphone".')) ipcRenderer.send('open-mic-settings');
      else warn('Microphone access is blocked. In Windows: Settings > Privacy & security > Microphone > "Let desktop apps access your microphone".');
    };
    try {
      if (ipcRenderer) { const st = await ipcRenderer.invoke('mic-status'); if (st === 'denied' || st === 'restricted') { openMicSettings(); return; } }
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach(t => t.stop());
    } catch (e) {
      if (e && e.name === 'NotFoundError') warn('No microphone was found. Plug one in and try again.');
      else openMicSettings();
      return;
    }

    const rec = new SpeechRecognition();
    rec.lang = navigator.language || 'en-US';
    rec.continuous = true;
    rec.interimResults = true;
    voiceBaseTextRef.current = newTaskText ? newTaskText.trimEnd() + ' ' : '';
    rec.onresult = (event) => {
      let transcript = '';
      for (let i = 0; i < event.results.length; i++) transcript += event.results[i][0].transcript;
      const annotated = annotateTranscript(transcript, categories, teamMembers);
      setNewTaskText(voiceBaseTextRef.current + annotated);
      requestAnimationFrame(() => {
        const el = newTaskInputRef.current;
        if (el) { el.style.height = 'auto'; el.style.height = Math.min(el.scrollHeight, 150) + 'px'; }
      });
    };
    // Report the real reason instead of silently switching the button back.
    rec.onerror = (e) => {
      const code = e.error;
      if (code === 'not-allowed' || code === 'service-not-allowed') openMicSettings();
      else if (code === 'network') warn('Voice dictation could not reach the speech service (error: network). If this keeps happening in the desktop app, try Windows voice typing instead: click the task box and press Win + H.');
      else if (code === 'audio-capture') warn('No working microphone was found.');
      else if (code === 'no-speech') warn("I didn't hear anything. Press the microphone and start speaking.");
      else if (code !== 'aborted') warn('Voice dictation stopped (' + code + ').');
      setIsListening(false);
    };
    rec.onend = () => setIsListening(false);
    recognitionRef.current = rec;
    try { rec.start(); setIsListening(true); } catch (e) { warn('Could not start voice dictation: ' + e.message); }
  }, [isListening, newTaskText, categories, teamMembers, ipcRenderer]);

