  // CLICK vs DRAG: the browser starts a drag after only a few pixels of movement and then swallows the click, so a
  // click with a slightly moving mouse never opened the task. Now a "drag" that ends within CLICK_MAX_MOVE pixels of
  // where it started (or a very quick tap) counts as a click and opens the task.
  const CLICK_MAX_MOVE = 12;
  const pressRef = useRef({ x:0, y:0, t:0 });
  const lastDragPosRef = useRef({ x:0, y:0 });
  const dragHandlers = useCallback((task) => ({
    onMouseDown: (e) => { dragMovedRef.current = false; pressRef.current = { x:e.clientX, y:e.clientY, t:Date.now() }; lastDragPosRef.current = { x:e.clientX, y:e.clientY }; },
    onDragStart: (e) => { e.dataTransfer.effectAllowed = 'move'; dragMovedRef.current = true; setDraggingTask(task); setDragOverTaskId(null); },
    onDrag: (e) => { if (e.clientX || e.clientY) lastDragPosRef.current = { x:e.clientX, y:e.clientY }; }, // the very last drag event reports 0,0, so keep the last real position
    onDragEnd: (e) => {
      const p = pressRef.current;
      const q = (e.clientX || e.clientY) ? { x:e.clientX, y:e.clientY } : lastDragPosRef.current;
      const dist = Math.hypot(q.x - p.x, q.y - p.y);
      const wasClick = dist < CLICK_MAX_MOVE || (Date.now() - p.t < 120 && dist < 30);
      setDraggingTask(null); setDragOverCol(null); setDragOverTaskId(null);
      setTimeout(() => { dragMovedRef.current = false; }, 50);
      if (wasClick) openModal(task);
    },
  }), [openModal]);

