      const colTasks = tasks.filter(t=>t.status===targetCol && (targetCol!=='Yapılacaklar'||t.category===task.category)).sort((a,b)=>(a.order??a.createdAt??0)-(b.order??b.createdAt??0));
      const withoutSelf = colTasks.filter(t=>t.id!==task.id);
      const insertIdx = withoutSelf.findIndex(t=>t.id===insertBeforeTaskId);
