                    <input type="date" value={activeTask.dueDate||''} onChange={e=>updateDoc(doc(db,'tasks',activeTask.id),{dueDate:e.target.value||null,dueTime:null})} onClick={e=>{e.stopPropagation();try{e.target.showPicker&&e.target.showPicker();}catch(err){}}} style={{position:'absolute',inset:0,opacity:0,cursor:'pointer',width:'100%'}}/>
                    {activeTask.dueDate&&<span onClick={e=>{e.stopPropagation();e.preventDefault();updateDoc(doc(db,'tasks',activeTask.id),{dueDate:null,dueTime:null});}} style={{opacity:0.6,marginLeft:2}}>✕</span>}
