export const NebulaCanvas = React.memo(({ theme, enabled=true }) => {
  const canvasRef = useRef(null);
  useEffect(() => {
    if (!enabled) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    let raf;
    const resize = () => { canvas.width = window.innerWidth; canvas.height = window.innerHeight; };
    resize();
    window.addEventListener('resize', resize);
    const isDark = theme !== 'light';
    const count = 55;
    const particles = Array.from({length: count}, () => ({
      x: Math.random() * canvas.width, y: Math.random() * canvas.height,
      r: Math.random() * 1.6 + 0.4, dx: (Math.random() - 0.5) * 0.18, dy: (Math.random() - 0.5) * 0.18,
      alpha: Math.random() * 0.35 + 0.08,
      hue: isDark ? (Math.random() < 0.5 ? 200 : 260) : (Math.random() < 0.5 ? 210 : 170),
    }));
    // NOTE TO SELF: these blob colors are drawn via the Canvas 2D API (ctx.fillStyle),
    // NOT CSS — CSS custom properties like var(--accent) do NOT resolve inside Canvas
    // fillStyle strings, so these must stay literal rgba() values. Do not "fix" them
    // to track the user's chosen accent color; a prior pass did this by mistake and
    // it silently produced invalid/no-op fill colors until reverted.
    const blobs = isDark
      ? [{x:0.2,y:0.3,r:320,c:'rgba(56,189,248,0.025)'},{x:0.75,y:0.6,r:280,c:'rgba(168,85,247,0.022)'},{x:0.5,y:0.85,r:250,c:'rgba(16,185,129,0.018)'}]
      : [{x:0.15,y:0.25,r:300,c:'rgba(49,130,206,0.055)'},{x:0.8,y:0.55,r:260,c:'rgba(56,189,248,0.045)'},{x:0.5,y:0.9,r:220,c:'rgba(129,230,217,0.04)'}];
    const draw = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      blobs.forEach(b => {
        const grd = ctx.createRadialGradient(b.x*canvas.width, b.y*canvas.height, 0, b.x*canvas.width, b.y*canvas.height, b.r);
        grd.addColorStop(0, b.c); grd.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = grd; ctx.fillRect(0, 0, canvas.width, canvas.height);
      });
      particles.forEach(p => {
        p.x += p.dx; p.y += p.dy;
        if (p.x < 0) p.x = canvas.width; if (p.x > canvas.width) p.x = 0;
        if (p.y < 0) p.y = canvas.height; if (p.y > canvas.height) p.y = 0;
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI*2);
        ctx.fillStyle = isDark ? `hsla(${p.hue},80%,72%,${p.alpha})` : `hsla(${p.hue},65%,45%,${p.alpha * 0.7})`;
        ctx.fill();
      });
      raf = requestAnimationFrame(draw);
    };
    draw();
    return () => { cancelAnimationFrame(raf); window.removeEventListener('resize', resize); };
  }, [theme, enabled]);
  return <canvas ref={canvasRef} style={{position:'fixed',inset:0,zIndex:0,pointerEvents:'none',opacity:enabled?1:0}}/>;
});

export const EmptyState = React.memo(({ icon, title, desc }) => (
  <div style={{ display:'flex', flexDirection:'column', alignItems:'center', padding:'36px 24px', textAlign:'center', gap:14 }}>
    <div style={{ fontSize:56, animation:'emptyFloat 3s ease infinite', lineHeight:1 }}>{icon}</div>
    <div style={{ fontSize:15, fontWeight:'800', opacity:0.65, letterSpacing:-0.3 }}>{title}</div>
    <div style={{ fontSize:12, opacity:0.38, maxWidth:280, lineHeight:1.7 }}>{desc}</div>
  </div>
));

export const DonutChart = React.memo(({ data, size=190, T }) => {
  const total = useMemo(() => data.reduce((s,x) => s+x.value, 0), [data]);
  const slices = useMemo(() => {
    if (!total) return [];
    let angle = -Math.PI / 2;
    const cx=size/2, cy=size/2, R=size/2-10, r=R*0.56;
    return data.map(item => {
      const sweep=(item.value/total)*2*Math.PI, end=angle+sweep, large=sweep>Math.PI?1:0;
      const c1=[Math.cos(angle),Math.sin(angle)], c2=[Math.cos(end),Math.sin(end)];
      const path=[`M ${(cx+R*c1[0]).toFixed(2)} ${(cy+R*c1[1]).toFixed(2)}`,`A ${R} ${R} 0 ${large} 1 ${(cx+R*c2[0]).toFixed(2)} ${(cy+R*c2[1]).toFixed(2)}`,`L ${(cx+r*c2[0]).toFixed(2)} ${(cy+r*c2[1]).toFixed(2)}`,`A ${r} ${r} 0 ${large} 0 ${(cx+r*c1[0]).toFixed(2)} ${(cy+r*c1[1]).toFixed(2)}`,'Z'].join(' ');
      angle = end;
      return { ...item, path, pct: Math.round(item.value/total*100) };
    });
  }, [data, total, size]);
  if (!total) return <EmptyState icon="🎯" title="No data yet" desc="You'll see great charts here once you finish your first task!" />;
  const cx=size/2, cy=size/2;
  return (
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ color:T.text, overflow:'visible' }}>
      {slices.map((s,i) => <path key={i} d={s.path} fill={s.color} opacity={0.9}><title>{s.label}: {s.value} ({s.pct}%)</title></path>)}
      <text x={cx} y={cy-10} textAnchor="middle" fill="currentColor" fontSize={28} fontWeight="900">{total}</text>
      <text x={cx} y={cy+10} textAnchor="middle" fill="currentColor" fontSize={10} opacity={0.45}>done</text>
    </svg>
  );
});

export const Heatmap = React.memo(({ tasks, T }) => {
  const { weeks, maxCount } = useMemo(() => {
    const map = {};
    tasks.filter(t => t.completedAt).forEach(t => { const key=new Date(toMs(t.completedAt)).toLocaleDateString('en-CA'); map[key]=(map[key]||0)+1; });
    const max = Math.max(...Object.values(map), 1);
    const today = new Date(); today.setHours(23,59,59,999);
    const start = new Date(today); start.setDate(start.getDate()-90);
    const dow = (start.getDay()+6)%7; start.setDate(start.getDate()-dow);
    const ws = []; const cur = new Date(start);
    while (cur <= today) {
      const w = [];
      for (let d=0; d<7; d++) { const key=cur.toLocaleDateString('en-CA'); w.push({key,count:map[key]||0,isFuture:new Date(cur)>today,date:new Date(cur)}); cur.setDate(cur.getDate()+1); }
      ws.push(w);
    }
    return { weeks:ws, maxCount:max };
  }, [tasks]);
  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const dayLbls=['Mon','','Wed','','Fri','','Sun'];
  if (!weeks.some(w => w.some(c => c.count > 0))) return <EmptyState icon="📅" title="No activity found" desc="The heatmap will light up as you complete tasks!" />;
  return (
    <div style={{ display:'flex', gap:3, alignItems:'flex-start', overflowX:'auto', paddingBottom:4 }}>
      <div style={{ display:'flex', flexDirection:'column', gap:2, paddingTop:18, paddingRight:4, flexShrink:0 }}>
        {dayLbls.map((l,i) => <div key={i} style={{ height:12, fontSize:8, color:T.muted, lineHeight:'12px', width:24, textAlign:'right' }}>{l}</div>)}
      </div>
      <div style={{ flexShrink:0 }}>
        <div style={{ display:'flex', gap:2, marginBottom:3, height:14 }}>
          {weeks.map((w,wi) => { const show=w[0].date.getDate()<=7; return <div key={wi} style={{ width:12, fontSize:8, color:T.muted, lineHeight:'14px', overflow:'visible', whiteSpace:'nowrap' }}>{show?months[w[0].date.getMonth()]:''}</div>; })}
        </div>
        <div style={{ display:'flex', flexDirection:'column', gap:2 }}>
          {Array.from({length:7}, (_,di) => (
            <div key={di} style={{ display:'flex', gap:2 }}>
              {weeks.map((w,wi) => { const c=w[di]; const intensity=c.count/maxCount; return <div key={wi} title={`${c.date.toLocaleDateString('en-US')}: ${c.count} task(s)`} style={{ width:12,height:12,borderRadius:2,cursor:c.count?'pointer':'default',transition:'transform 0.15s',backgroundColor:c.isFuture?'transparent':c.count===0?T.border:`color-mix(in srgb, var(--accent,#38bdf8) ${((0.2+intensity*0.8)*100).toFixed(0)}%, transparent)`,border:c.isFuture?`1px solid ${T.border}`:'none'}} onMouseOver={e=>e.currentTarget.style.transform='scale(1.5)'} onMouseOut={e=>e.currentTarget.style.transform='scale(1)'}/>; })}
            </div>
          ))}
        </div>
      </div>
      <div style={{ display:'flex', flexDirection:'column', gap:3, paddingTop:18, paddingLeft:8, flexShrink:0 }}>
        <span style={{ fontSize:8, color:T.muted }}>Less</span>
        <div style={{ display:'flex', flexDirection:'column', gap:2 }}>
          {[0.15,0.35,0.55,0.75,1].map((v,i) => <div key={i} style={{ width:10, height:10, borderRadius:2, backgroundColor:`color-mix(in srgb, var(--accent,#38bdf8) ${(v*100).toFixed(0)}%, transparent)` }} />)}
        </div>
        <span style={{ fontSize:8, color:T.muted }}>More</span>
      </div>
    </div>
  );
});

export const StatCard = React.memo(({ icon, label, value, sub, color, T }) => (
  <div className="stat-card" style={{ backgroundColor:T.sub, borderRadius:16, padding:'16px 18px', border:`1px solid ${T.border}`, display:'flex', flexDirection:'column', gap:4, position:'relative', overflow:'hidden', transition:'all 0.25s cubic-bezier(.175,.885,.32,1.275)', cursor:'default' }}>
    <div style={{ position:'absolute', top:-10, right:-10, fontSize:50, opacity:0.06, pointerEvents:'none' }}>{icon}</div>
    <span style={{ fontSize:10, color:T.muted, fontWeight:'700', letterSpacing:0.5 }}>{label}</span>
    <span style={{ fontSize:24, fontWeight:'900', color:color||T.text, lineHeight:1 }}>{value}</span>
    {sub && <span style={{ fontSize:11, color:T.muted }}>{sub}</span>}
  </div>
));

export const SideBtn = React.memo(({ icon, label, expanded, onClick, active }) => (
  <button onClick={onClick} className={`nav-btn${active?' nav-btn-active':''}`}
    style={{ width:expanded?'85%':'46px', height:46, borderRadius:12, border:'none', backgroundColor:active?'#1a3a4a':'#1e293b', color:active?'var(--accent,#38bdf8)':'#94a3b8', cursor:'pointer', marginBottom:10, display:'flex', alignItems:'center', justifyContent:expanded?'flex-start':'center', gap:14, padding:'0 14px', transition:'all 0.3s cubic-bezier(.175,.885,.32,1.275)', overflow:'hidden', whiteSpace:'nowrap', position:'relative', flexShrink:0, boxShadow:active?'inset 0 0 0 1px color-mix(in srgb, var(--accent,#38bdf8) 35%, transparent)':'none' }}>
    <span style={{ fontSize:18, flexShrink:0 }}>{icon}</span>
    {expanded && <span style={{ fontWeight:'700', fontSize:13 }}>{label}</span>}
  </button>
));

export const CatBtn = React.memo(({ label, active, color, onClick, T, dot }) => (
  <button onClick={onClick} style={{ padding:'5px 14px', borderRadius:20, border:`1px solid ${active?color:T.border}`, background:active?color:T.card, color:active?'#fff':T.text, cursor:'pointer', fontSize:11, fontWeight:'800', display:'flex', alignItems:'center', gap:6, transition:'all 0.22s cubic-bezier(.175,.885,.32,1.275)', transform:active?'translateY(-1px)':'none', boxShadow:active?`0 4px 14px color-mix(in srgb, ${color} 33%, transparent)`:'none' }}>
    {dot && <span style={{ width:7, height:7, borderRadius:'50%', background:active?'#fff':color, flexShrink:0 }} />}
    {label}
  </button>
));

export const Backdrop = React.memo(({ onClick, children }) => (
  <div style={{ position:'fixed', inset:0, zIndex:10000, backgroundColor:'rgba(0,0,0,0.78)', display:'flex', justifyContent:'center', alignItems:'center', backdropFilter:'blur(12px)', animation:'overlayIn 0.28s ease' }} onClick={onClick}>{children}</div>
));

export const ModalBox = React.memo(({ T, width, children, maxHeight }) => (
  <div style={{ width, maxHeight, overflowY: maxHeight?'auto':undefined, backgroundColor:T.card, padding:28, borderRadius:26, border:`1px solid ${T.border}`, boxShadow:'0 40px 100px rgba(0,0,0,0.55)', animation:'modalIn 0.32s cubic-bezier(.175,.885,.32,1.275)', boxSizing:'border-box' }} onClick={e=>e.stopPropagation()}>{children}</div>
));