// src/migrations.js — brings a team's stored data up to the format this version of the app expects.
//
// HOW IT WORKS: every team document carries `schemaVersion`. When any member opens the app
// and the team's schemaVersion is lower than DATA_SCHEMA_VERSION, App.js calls runMigrations()
// once, which runs the missing steps in order and records progress on the team document.
// New teams are created at the current version, so they never need migrating.
//
// RULES FOR ADDING A MIGRATION (so old and new app versions can coexist during rollout):
//   1. Append { version: N+1, name, run } below and bump DATA_SCHEMA_VERSION to N+1.
//   2. Make `run` IDEMPOTENT (safe to run twice, two members may trigger it at once) and
//      ADDITIVE (add / fill fields; don't delete or rename fields that a still-running older
//      app version reads). Remove old fields only in a later migration, once the required
//      app version has moved past every client that reads them.

import { collection, doc, getDocs, query, where, updateDoc, writeBatch } from 'firebase/firestore';

export const DATA_SCHEMA_VERSION = 1;

const MIGRATIONS = [
  {
    version: 1,
    name: 'Normalize older task documents',
    async run(db, teamId) {
      // (The team password is no longer migrated here: it moves to team_secrets when the first person joins, see accounts.js.)

      // b) Older tasks may lack fields newer features read. Fill only what is missing.
      const snap = await getDocs(query(collection(db, 'tasks'), where('teamId', '==', teamId)));
      let batch = writeBatch(db);
      let ops = 0;
      for (const d of snap.docs) {
        const t = d.data();
        const patch = {};
        if (!Array.isArray(t.subTasks)) patch.subTasks = [];
        if (!Array.isArray(t.comments)) patch.comments = [];
        if (!Array.isArray(t.labels)) patch.labels = [];
        if (!Array.isArray(t.images)) patch.images = [];
        else if (t.images.some((i) => typeof i === 'string')) patch.images = t.images.map((i) => (typeof i === 'string' ? { url: i, name: 'image' } : i));
        ['priority', 'dueDate', 'dueTime', 'recurrence'].forEach((k) => { if (t[k] === undefined) patch[k] = null; });
        if (Object.keys(patch).length) {
          batch.update(d.ref, patch);
          ops++;
          if (ops === 15) { await batch.commit(); batch = writeBatch(db); ops = 0; } // small batches: the security rules read the member doc for each write, and a batch may use at most 20 of those lookups
        }
      }
      if (ops > 0) await batch.commit();
    },
  },
];

export async function runMigrations(db, teamId, fromVersion) {
  const teamRef = doc(db, 'teams', teamId);
  for (const m of MIGRATIONS) {
    if (m.version <= fromVersion) continue;
    console.log(`🔄 Data migration ${m.version}: ${m.name}`);
    await m.run(db, teamId);
    await updateDoc(teamRef, { schemaVersion: m.version });
  }
}