// src/auth.js — password hashing + "is this password too easy?" checks.
//
// NOTE TO SELF (honest limitation, don't oversell this): the app has no server and no
// Firebase Auth. Passwords are hashed in the browser (PBKDF2-SHA256, random salt per
// password) and the hash is stored in Firestore next to the member / team document; the
// check happens in the client. That stops casual "type someone else's name and walk in"
// and keeps plaintext passwords out of the database, but it is NOT server-enforced: anyone
// who can read/write the Firestore project can read the hashes (to crack offline) or edit
// them. Real enforcement = Firebase Authentication + security rules. If that becomes
// necessary, this file's record format ({pwSalt, pwHash, pwIter}) is the thing to replace.

const enc = new TextEncoder();
const toB64 = (buf) => { let s = ''; const a = new Uint8Array(buf); for (let i = 0; i < a.length; i++) s += String.fromCharCode(a[i]); return btoa(s); };
const fromB64 = (b) => Uint8Array.from(atob(b), (c) => c.charCodeAt(0));

export const PBKDF2_ITER = 120000;
export const MIN_PASSWORD_LEN = 6; // hard minimum; anything weaker than "good" only gets a warning

async function derive(password, salt, iter) {
  const key = await crypto.subtle.importKey('raw', enc.encode(password.normalize('NFC')), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: iter }, key, 256);
  return toB64(bits);
}

const sameString = (a, b) => {
  if (a.length !== b.length) return false;
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
};

// Hash of `password` with a stored salt + iteration count (used for the team password's join key).
export const deriveHash = (password, saltB64, iter) => derive(password, fromB64(saltB64), iter || PBKDF2_ITER);

export const hasPasswordHash = (rec) => !!(rec && rec.pwHash && rec.pwSalt);

export async function makePasswordRecord(password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  return { pwSalt: toB64(salt), pwHash: await derive(password, salt, PBKDF2_ITER), pwIter: PBKDF2_ITER };
}

export async function checkPassword(password, rec) {
  if (!hasPasswordHash(rec)) return false;
  const h = await derive(password, fromB64(rec.pwSalt), rec.pwIter || PBKDF2_ITER);
  return sameString(h, rec.pwHash);
}

const COMMON = new Set([
  '123456', '1234567', '12345678', '123456789', '1234567890', '12345', '654321', '111111', '000000', '123123', '121212',
  'password', 'password1', 'password123', 'parola', 'parola123', 'sifre', 'sifre123', 'şifre', 'şifre123',
  'qwerty', 'qwerty123', 'qwertyuiop', 'asdfgh', 'asdfghjkl', 'zxcvbnm', 'abc123', 'abcdef', '1q2w3e', '1q2w3e4r',
  'iloveyou', 'admin', 'admin123', 'welcome', 'letmein', 'crem', 'c-rem', 'crem123', 'demo', 'demo123', 'test', 'test123',
]);
const SEQS = ['0123456789', '9876543210', 'abcdefghijklmnopqrstuvwxyz', 'zyxwvutsrqponmlkjihgfedcba', 'qwertyuiop', 'asdfghjkl', 'zxcvbnm'];

// 4+ digits in a row (1234, 4321) or 5+ letters in a row (abcde, qwert), anywhere in the password.
const hasRun = (lower) => {
  for (const seq of SEQS) {
    const need = /\d/.test(seq[0]) ? 4 : 5;
    for (let i = 0; i + need <= lower.length; i++) if (seq.includes(lower.slice(i, i + need))) return true;
  }
  return false;
};

// Returns a list of human-readable reasons the password is easy to guess ([] = fine).
export function passwordWeakness(pw, names = []) {
  const reasons = [];
  const lower = pw.toLowerCase();
  if (pw.length < 8) reasons.push('it is shorter than 8 characters');
  if (COMMON.has(lower)) reasons.push('it is one of the most commonly used passwords');
  else if (/^(.)\1+$/u.test(pw)) reasons.push('it is one character repeated');
  else if (hasRun(lower)) reasons.push('it contains an obvious run like 1234 or abcde');
  const classes = [/\p{Ll}/u, /\p{Lu}/u, /\p{Nd}/u, /[^\p{L}\p{Nd}]/u].filter((r) => r.test(pw)).length;
  if (pw.length >= 8 && pw.length < 12 && classes < 2) reasons.push('it uses only one kind of character');
  if (names.some((n) => n && n.trim().length >= 3 && lower.includes(n.trim().toLowerCase()))) reasons.push('it contains your name or the team name');
  return reasons;
}

// One place for the "new password" rules so onboarding and the setup modal behave identically.
// Returns { error } (blocked), { weak: [...] } (warn first; call again with acknowledged=true to accept), or { ok: true }.
export function checkNewPassword(pw, pw2, names, acknowledged) {
  if (pw.length < MIN_PASSWORD_LEN) return { error: `Password must be at least ${MIN_PASSWORD_LEN} characters.` };
  if (pw !== pw2) return { error: "The two passwords don't match." };
  const weak = passwordWeakness(pw, names);
  if (weak.length && !acknowledged) return { weak };
  return { ok: true };
}