import * as chrono from 'chrono-node';
import { STATUS_LABELS, PRIORITY_META, RECURRENCE_META, PRIORITY_WORD_MAP, OFFICIAL_SITE_HOSTS } from './constants';

export const priorityMeta = id => PRIORITY_META.find(p=>p.id===id) || null;
export const recurrenceMeta = id => RECURRENCE_META.find(r=>r.id===id) || null;
export const statusLabel = s => STATUS_LABELS[s] || s;

export const escapeRe = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

// Computes the next due date string (YYYY-MM-DD) for a recurring task, based off its previous
// due date if it had one, otherwise off today.
export function nextRecurrenceDate(recurrence, fromDateStr) {
  const base = fromDateStr ? new Date(fromDateStr + 'T00:00:00') : new Date();
  const d = new Date(base);
  if (recurrence === 'daily') d.setDate(d.getDate() + 1);
  else if (recurrence === 'weekly') d.setDate(d.getDate() + 7);
  else if (recurrence === 'monthly') {
    // Clamp to the target month's actual last day instead of letting setMonth() roll
    // over into the following month (e.g. Jan 31 -> Feb 28/29, not Mar 3).
    const targetMonthIndex = base.getMonth() + 1;
    const targetYear = base.getFullYear() + Math.floor(targetMonthIndex / 12);
    const targetMonth = targetMonthIndex % 12;
    const daysInTargetMonth = new Date(targetYear, targetMonth + 1, 0).getDate();
    d.setFullYear(targetYear, targetMonth, Math.min(base.getDate(), daysInTargetMonth));
  }
  else return null;
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

// Parses free-form quick-add text like "Fix login bug tomorrow 3pm @development #p1 +Alex Carter"
// into { title, category, priority, dueDate, dueTime, assignee } — mirrors Todoist-style natural
// language input. Symbols: @category, #priority, +assignee. Bare words (no symbol) are also
// matched as a fallback for voice dictation, which can't naturally produce "@"/"#"/"+". Detected
// tokens are stripped out of the returned title. Any field not detected comes back null.
export function parseQuickAdd(rawText, categories, teamMembers=[]) {
  let text = rawText;
  let category = null, priority = null, dueDate = null, dueTime = null, assignee = null;

  // 1) @category (symbol) then bare category name as fallback
  const catMatch = text.match(/@(\w+)/);
  if (catMatch) {
    const found = categories.find(c => c.name.toLowerCase() === catMatch[1].toLowerCase());
    if (found) { category = found.name; text = text.slice(0, catMatch.index) + text.slice(catMatch.index + catMatch[0].length); }
  }
  if (!category) {
    for (const c of categories) {
      const m = text.match(new RegExp(`\\b${escapeRe(c.name)}\\b`, 'i'));
      if (m) { category = c.name; text = text.slice(0, m.index) + text.slice(m.index + m[0].length); break; }
    }
  }

  // 2) #priority (symbol) then bare priority word as fallback
  const priMatch = text.match(/#(p[1-4]|urgent|high|medium|low)\b/i);
  if (priMatch) {
    priority = PRIORITY_WORD_MAP[priMatch[1].toLowerCase()] || null;
    if (priority) text = text.slice(0, priMatch.index) + text.slice(priMatch.index + priMatch[0].length);
  }
  if (!priority) {
    const m = text.match(/\b(p[1-4]|urgent|high priority|high|medium|low priority|low)\b/i);
    if (m) {
      const key = m[1].toLowerCase().replace(' priority','');
      priority = PRIORITY_WORD_MAP[key] || null;
      if (priority) text = text.slice(0, m.index) + text.slice(m.index + m[0].length);
    }
  }

  // 3) +assignee (symbol) then bare team-member name as fallback (longest name first, avoids
  //    "Alex" partially matching inside "Alex Carter")
  const sortedMembers = [...teamMembers].sort((a,b)=>(b.userName||'').length-(a.userName||'').length);
  const plusIdx = text.indexOf('+');
  if (plusIdx !== -1) {
    const after = text.slice(plusIdx+1);
    const m = sortedMembers.find(mem => mem.userName && new RegExp(`^${escapeRe(mem.userName)}\\b`, 'i').test(after));
    if (m) { assignee = m.userName; text = text.slice(0, plusIdx) + text.slice(plusIdx+1+m.userName.length); }
  }
  if (!assignee) {
    for (const m of sortedMembers) {
      if (!m.userName) continue;
      const match = text.match(new RegExp(`\\b${escapeRe(m.userName)}\\b`, 'i'));
      if (match) { assignee = m.userName; text = text.slice(0, match.index) + text.slice(match.index + match[0].length); break; }
    }
  }

  // 4) Natural-language date via chrono-node (e.g. "tomorrow", "next friday", "in 3 days", "aug 30")
  const results = chrono.parse(text, new Date(), { forwardDate: true });
  if (results.length) {
    const r = results[0];
    const d = r.start.date();
    dueDate = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    if (r.start.isCertain('hour')) {
      dueTime = `${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
    }
    text = text.slice(0, r.index) + text.slice(r.index + r.text.length);
  }

  const title = text.replace(/\s{2,}/g, ' ').trim();
  return { title, category, priority, dueDate, dueTime, assignee };
}

// Inserts @/#/+ symbols directly in front of recognized tokens within the visible text, without
// removing anything — used right after voice dictation so the person can SEE what got picked up
// before submitting (e.g. "content P3 Alex Carter" -> "@content #P3 +Alex Carter").
export function annotateTranscript(rawText, categories, teamMembers=[]) {
  const matches = [];
  const collect = (re, symbol) => {
    const seen = new Set();
    let m;
    const r = new RegExp(re, 'gi');
    while ((m = r.exec(rawText))) {
      const start = m.index;
      if (rawText[start-1] === symbol) continue; // already annotated
      if (seen.has(start)) continue;
      seen.add(start);
      matches.push({ index: start, length: m[0].length, symbol });
    }
  };
  categories.forEach(c => collect(`\\b${escapeRe(c.name)}\\b`, '@'));
  collect(`\\b(p[1-4]|urgent|high priority|high|medium|low priority|low)\\b`, '#');
  [...teamMembers].sort((a,b)=>(b.userName||'').length-(a.userName||'').length).forEach(m => {
    if (m.userName) collect(`\\b${escapeRe(m.userName)}\\b`, '+');
  });
  matches.sort((a,b)=>b.index-a.index); // insert from the end so earlier indices stay valid
  let out = rawText;
  const usedRanges = [];
  for (const m of matches) {
    if (usedRanges.some(r => m.index < r.end && m.index+m.length > r.start)) continue; // no overlap
    out = out.slice(0, m.index) + m.symbol + out.slice(m.index);
    usedRanges.push({ start: m.index, end: m.index + m.length + 1 });
  }
  return out;
}

export const toMs = ts => {
  if (!ts || typeof ts !== 'number') return null;
  return ts < 9_999_999_999 ? ts * 1000 : ts;
};

export const formatDuration = ms => {
  if (!ms || ms <= 0) return null;
  const d = Math.floor(ms / 86400000);
  const h = Math.floor((ms % 86400000) / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  if (d > 0) return h > 0 ? `${d}d ${h}h` : `${d}d`;
  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
  if (m > 0) return `${m}m`;
  return '< 1 min';
};

export const formatActiveDur = ms => {
  if (!ms || ms <= 0) return 'just now';
  const d = Math.floor(ms / 86400000);
  const h = Math.floor((ms % 86400000) / 3600000);
  const m = Math.floor((ms % 3600000) / 60000);
  if (d > 0) return h > 0 ? `${d}d ${h}h` : `${d}d`;
  if (h > 0) return m > 0 ? `${h}h ${m}m` : `${h}h`;
  if (m > 0) return `${m}m`;
  return 'just now';
};

export const statusGlow = (status, cc, isLate, primaryBranchColor) => {
  if (isLate && status === 'Devam Edenler') return '#ef4444';
  if (status === 'Tamamlandı') return '#10b981';
  if (status === 'Hatalılar') return '#ef4444';
  if (status === 'Kontrol Edilecekler') return '#f59e0b';
  if (status === 'Devam Edenler') return primaryBranchColor || cc;
  return cc;
};

// true only for https links on an official C-Rem site host (see OFFICIAL_SITE_HOSTS in constants.js)
export const isOfficialLink = (url) => {
  try { const u = new URL(url); return u.protocol === 'https:' && OFFICIAL_SITE_HOSTS.includes(u.hostname); }
  catch (e) { return false; }
};
