// src/accounts.js — accounts and team membership on top of Firebase Authentication.
//
// HOW IT FITS TOGETHER (read this before touching firestore.rules):
//  • Firebase Auth does the password checking. Auth needs an email, but we collect none, so each account
//    gets a random internal one (<random>@crem.invalid). The person never sees it.
//  • "Sign in with name + password" works through `logins/{key}`, key = SHA-256(teamId + name). That doc
//    (publicly gettable, not listable) maps a name to the account's internal email. It also enforces unique
//    names per team and lets a rename change the name without touching the Auth email.
//  • `team_members/{uid}` says which team an account belongs to. The security rules read it to decide what
//    the signed-in user may touch. It also holds `joinKey` = the team password's PBKDF2 hash, which the rules
//    compare with `team_secrets/{teamId}.pwHash` (a doc no client can read) to prove the joiner knew the team password.
//  • `teams/{teamId}` is public to get: team name + the salt/iterations needed to derive the join key.
//
// Legacy teams (2.1.x and older) keep the team-password hash on the team doc itself. The first person to join
// such a team "adopts" it: the hash moves to team_secrets and is removed from the public team doc. That only
// works while the Firestore rules are still open, so adopt every existing team BEFORE locking the rules.

import {
  createUserWithEmailAndPassword, signInWithEmailAndPassword, signOut,
  EmailAuthProvider, reauthenticateWithCredential, deleteUser,
} from 'firebase/auth';
import { doc, getDoc, getDocs, updateDoc, writeBatch, addDoc, collection, query, where, deleteField } from 'firebase/firestore';
import db, { auth } from './firebase';
import { makePasswordRecord, deriveHash, checkPassword } from './auth';
import { DATA_SCHEMA_VERSION } from './migrations';

const fail = (code, message) => Object.assign(new Error(message || code), { code });

// True while sign-up is half done (Auth user exists, membership docs not written yet), so the app
// doesn't mistake that moment for "signed in without a team" and sign the person out.
let busy = false;
export const isAccountOpBusy = () => busy;

const enc = new TextEncoder();
const sha256Hex = async (s) => [...new Uint8Array(await crypto.subtle.digest('SHA-256', enc.encode(s)))].map((x) => x.toString(16).padStart(2, '0')).join('');
const randomHex = (bytes = 12) => [...crypto.getRandomValues(new Uint8Array(bytes))].map((x) => x.toString(16).padStart(2, '0')).join('');

export const teamIdFromName = (name) => name.trim().toLowerCase().replace(/[^a-z0-9]/g, '_');
export const normName = (n) => n.trim().normalize('NFC').toLowerCase();
export const loginKey = (teamId, name) => sha256Hex(`${teamId}\n${normName(name)}`);

const mapAuthError = (e) => {
  switch (e && e.code) {
    case 'auth/invalid-credential': case 'auth/wrong-password': case 'auth/user-not-found': case 'auth/invalid-login-credentials':
      return fail('bad-password', 'Incorrect password');
    case 'auth/too-many-requests': return fail('too-many', 'Too many attempts');
    case 'auth/weak-password': return fail('weak-password', 'Password too weak');
    case 'auth/network-request-failed': return fail('network', 'No connection');
    case 'auth/operation-not-allowed': case 'auth/configuration-not-found': return fail('auth-disabled', 'Email/Password sign-in is not enabled');
    default: return e;
  }
};

export async function getTeamPublic(teamId) {
  const s = await getDoc(doc(db, 'teams', teamId));
  return s.exists() ? s.data() : null;
}

export async function accountExists(teamId, name) {
  return (await getDoc(doc(db, 'logins', await loginKey(teamId, name)))).exists();
}

export async function loadSession(uid) {
  const m = await getDoc(doc(db, 'team_members', uid));
  if (!m.exists() || !m.data().teamId) return null;
  const t = await getDoc(doc(db, 'teams', m.data().teamId));
  return { uid, teamId: m.data().teamId, userName: m.data().userName, teamName: t.exists() ? t.data().name : m.data().teamId };
}

export async function signInAccount(teamId, name, password) {
  busy = true;
  try {
    const l = await getDoc(doc(db, 'logins', await loginKey(teamId, name)));
    if (!l.exists()) throw fail('no-account', 'No such account');
    try { await signInWithEmailAndPassword(auth, l.data().email, password); } catch (e) { throw mapAuthError(e); }
    const session = await loadSession(auth.currentUser.uid);
    if (!session) { await signOut(auth); throw fail('no-account', 'This account is no longer a member of a team'); }
    updateDoc(doc(db, 'team_members', session.uid), { lastSeen: Date.now() }).catch(() => {});
    return session;
  } finally { busy = false; }
}

async function createAuthUser(password) {
  const email = `${randomHex()}@crem.invalid`;
  try { return { cred: await createUserWithEmailAndPassword(auth, email, password), email }; } catch (e) { throw mapAuthError(e); }
}

// Join an existing team with a new account.
export async function createAccountAndJoin({ teamId, teamPassword, name, password }) {
  const td = await getTeamPublic(teamId);
  if (!td) throw fail('no-team', 'Team not found');
  if (await accountExists(teamId, name)) throw fail('name-taken', 'Name taken');

  // Work out the join key, verifying the team password here wherever the client is able to
  // (the security rules verify it again, and are the real gate once they are locked).
  let joinKey; let adopt = null;
  if (td.pwHash || td.password) { // legacy team: password still on the team doc
    const ok = td.pwHash ? await checkPassword(teamPassword || '', td) : td.password === teamPassword;
    if (!ok) throw fail('bad-team-password', 'Incorrect team password');
    adopt = td.pwHash ? { pwSalt: td.pwSalt, pwHash: td.pwHash, pwIter: td.pwIter } : await makePasswordRecord(teamPassword);
    joinKey = adopt.pwHash;
  } else {
    if (!teamPassword) throw fail('need-team-password', 'Team password needed');
    joinKey = await deriveHash(teamPassword, td.pwSalt, td.pwIter);
    try { // readable only while the rules are open; once locked this throws and the rules do the check
      const sec = await getDoc(doc(db, 'team_secrets', teamId));
      if (sec.exists() && sec.data().pwHash !== joinKey) throw fail('bad-team-password', 'Incorrect team password');
    } catch (e) { if (e.code === 'bad-team-password') throw e; }
  }

  busy = true;
  let created = null;
  try {
    created = await createAuthUser(password);
    const uid = created.cred.user.uid;
    const batch = writeBatch(db);
    if (adopt) {
      batch.set(doc(db, 'team_secrets', teamId), { pwHash: adopt.pwHash });
      batch.update(doc(db, 'teams', teamId), { pwSalt: adopt.pwSalt, pwIter: adopt.pwIter, pwHash: deleteField(), password: deleteField() });
    }
    batch.set(doc(db, 'team_members', uid), { teamId, userName: name, joinedAt: Date.now(), lastSeen: Date.now(), joinKey });
    batch.set(doc(db, 'logins', await loginKey(teamId, name)), { uid, email: created.email, teamId, createdAt: Date.now() });
    try { await batch.commit(); }
    catch (e) { throw (e && e.code === 'permission-denied') ? fail('bad-team-password', 'Incorrect team password') : e; }
    if (adopt) stripLegacyMemberSecrets(teamId);
    return await loadSession(uid);
  } catch (e) {
    if (created) await deleteUser(created.cred.user).catch(() => {});
    throw e;
  } finally { busy = false; }
}

// Creating a team: the team doc, its secret, the founder's membership and login all go in ONE batch, so there is
// never a moment where a team exists that nobody can use (and the rules can check them against each other).
export async function createTeamAndJoin({ teamName, teamPassword, name, password }) {
  const teamId = teamIdFromName(teamName);
  if (await getTeamPublic(teamId)) throw fail('team-exists', 'This team name is already in use');
  busy = true;
  let created = null;
  try {
    created = await createAuthUser(password);
    const uid = created.cred.user.uid;
    const rec = await makePasswordRecord(teamPassword);
    const batch = writeBatch(db);
    batch.set(doc(db, 'teams', teamId), { name: teamName.trim(), pwSalt: rec.pwSalt, pwIter: rec.pwIter, schemaVersion: DATA_SCHEMA_VERSION, createdAt: Date.now() });
    batch.set(doc(db, 'team_secrets', teamId), { pwHash: rec.pwHash });
    batch.set(doc(db, 'team_members', uid), { teamId, userName: name, joinedAt: Date.now(), lastSeen: Date.now(), joinKey: rec.pwHash });
    batch.set(doc(db, 'logins', await loginKey(teamId, name)), { uid, email: created.email, teamId, createdAt: Date.now() });
    await batch.commit();
    await addDoc(collection(db, 'categories'), { name: 'Design', color: '#a855f7', teamId, createdAt: Date.now() });
    await addDoc(collection(db, 'categories'), { name: 'Code', color: '#38bdf8', teamId, createdAt: Date.now() });
    return await loadSession(uid);
  } catch (e) {
    if (created) await deleteUser(created.cred.user).catch(() => {});
    throw e;
  } finally { busy = false; }
}

// Old member docs carry their own password hash fields; once the team is adopted, drop them (best effort).
async function stripLegacyMemberSecrets(teamId) {
  try {
    const snap = await getDocs(query(collection(db, 'team_members'), where('teamId', '==', teamId)));
    await Promise.all(snap.docs.filter((d) => d.data().pwHash).map((d) => updateDoc(d.ref, { pwHash: deleteField(), pwSalt: deleteField(), pwIter: deleteField() })));
  } catch (e) { console.warn('legacy member cleanup skipped:', e); }
}

// Renaming needs the password again (re-authentication), and the new name must be free in the team.
export async function renameAccount(newName, password) {
  const u = auth.currentUser;
  if (!u) throw fail('no-session', 'Not signed in');
  const m = await getDoc(doc(db, 'team_members', u.uid));
  if (!m.exists()) throw fail('no-session', 'Not signed in');
  const { teamId, userName: oldName } = m.data();
  try { await reauthenticateWithCredential(u, EmailAuthProvider.credential(u.email, password)); } catch (e) { throw mapAuthError(e); }
  const oldKey = await loginKey(teamId, oldName);
  const newKey = await loginKey(teamId, newName);
  const batch = writeBatch(db);
  if (newKey !== oldKey) {
    if ((await getDoc(doc(db, 'logins', newKey))).exists()) throw fail('name-taken', 'Name taken');
    batch.set(doc(db, 'logins', newKey), { uid: u.uid, email: u.email, teamId, createdAt: Date.now() });
    batch.delete(doc(db, 'logins', oldKey));
  }
  batch.update(doc(db, 'team_members', u.uid), { userName: newName });
  await batch.commit();
}

export const signOutUser = () => signOut(auth);
